1	// Servidor do Maxx: entrega o app (pasta public) e a API (/api/...).
2	import express from 'express';
3	import path from 'node:path';
4	import { fileURLToPath } from 'node:url';
5	import { initDb, q, one, dbKind } from './db.js';
6	import { config } from './config.js';
7	import { MEDAL_TYPES, MEDAL_BY_CODE, TROPHIES, TROPHY_BY_CODE, POINT_RULES, POINTS } from './rules.js';
8	import {
9	  HttpError, createPost, deletePost, toggleLike, addComment, deleteComment, giveMedal, revokeMedal,
10	  ranking, positions, totalPoints, getStats, checkTrophies, saveImageFromDataUrl,
11	} from './services.js';
12	import {
13	  hashPassword, checkPassword, createSession, destroySession, loadUser, requireUser, rateLimit, PUBLIC_USER_FIELDS,
14	} from './auth.js';
15	import { seedIfEmpty } from './seed.js';
16	
17	const here = path.dirname(fileURLToPath(import.meta.url));
18	const publicDir = path.join(here, '..', 'public');
19	
20	const int = (v) => {
21	  const n = Number.parseInt(v, 10);
22	  return Number.isFinite(n) ? n : null;
23	};
24	const clean = (v, max) => String(v ?? '').trim().slice(0, max);
25	
26	function requireRole(...roles) {
27	  return (req, _res, next) => {
28	    if (!req.user) throw new HttpError(401, 'Faça login para continuar.');
29	    if (!roles.includes(req.user.role)) throw new HttpError(403, 'Você não tem permissão para isso.');
30	    next();
31	  };
32	}
33	
34	function meJson(u) {
35	  return {
36	    id: u.id, name: u.name, role: u.role, email: u.email, course_id: u.course_id, course: u.course,
37	    course_name: u.course_name, semester: u.semester, bio: u.bio, avatar_id: u.avatar_id, is_guest: u.is_guest,
38	  };
39	}
40	
41	// Consulta base do feed: publicação + autor + contadores + detalhes de medalha.
42	const FEED_SELECT = `
43	  SELECT p.id, p.kind, p.image_id, p.caption, p.ref_code, p.created_at,
44	         u.id AS user_id, u.name AS user_name, u.avatar_id AS user_avatar, u.role AS user_role, u.is_guest AS user_guest,
45	         c.short AS user_course,
46	         (SELECT count(*) FROM likes l WHERE l.post_id = p.id)::int AS likes,
47	         (SELECT count(*) FROM comments cm WHERE cm.post_id = p.id)::int AS comments,
48	         EXISTS (SELECT 1 FROM likes l WHERE l.post_id = p.id AND l.user_id = $1) AS liked,
49	         m.id AS medal_id, m.type AS medal_type, m.reason AS medal_reason,
50	         pr.id AS prof_id, pr.name AS prof_name
51	    FROM posts p
52	    JOIN users u ON u.id = p.user_id
53	    LEFT JOIN courses c ON c.id = u.course_id
54	    LEFT JOIN medals m ON p.kind = 'medalha' AND m.id = p.ref_id
55	    LEFT JOIN users pr ON pr.id = m.professor_id`;
56	
57	function decoratePost(p) {
58	  if (p.kind === 'medalha') p.medal = MEDAL_BY_CODE[p.medal_type] || null;
59	  if (p.kind === 'trofeu') p.trophy = TROPHY_BY_CODE[p.ref_code] || null;
60	  return p;
61	}
62	
63	export async function createApp({ dataDir } = {}) {
64	  await initDb({ dataDir });
65	  if (config.seedDemo) await seedIfEmpty();
66	
67	  const app = express();
68	  app.set('trust proxy', 1); // Render/Cloudflare ficam na frente: confia no HTTPS deles
69	  app.disable('x-powered-by');
70	  app.use(express.json({ limit: '8mb' }));
71	  app.use((_req, res, next) => {
72	    res.set('X-Content-Type-Options', 'nosniff');
73	    res.set('Referrer-Policy', 'same-origin');
74	    next();
75	  });
76	  app.use('/api', loadUser);
77	
78	  // ---------- Público ----------
79	  app.get('/api/health', (_req, res) => res.json({ ok: true, db: dbKind() }));
80	
81	  app.get('/api/config', async (_req, res) => {
82	    const courses = await q('SELECT id, name, short FROM courses ORDER BY name');
83	    res.json({
84	      emailDomains: config.emailDomains,
85	      bancaEnabled: config.bancaEnabled,
86	      bancaNeedsCode: Boolean(config.bancaCode),
87	      courses,
88	      medalTypes: MEDAL_TYPES,
89	      pointRules: POINT_RULES,
90	      postPoints: POINTS.post,
91	    });
92	  });
93	
94	  app.get('/api/img/:id', async (req, res) => {
95	    const img = await one('SELECT mime, data FROM images WHERE id = $1', [int(req.params.id)]);
96	    if (!img) throw new HttpError(404, 'Imagem não encontrada.');
97	    res.set('Content-Type', img.mime);
98	    res.set('Cache-Control', 'public, max-age=31536000, immutable');
99	    if (img.mime === 'image/svg+xml') res.set('Content-Security-Policy', "default-src 'none'; style-src 'unsafe-inline'");
100	    res.send(Buffer.from(img.data));
101	  });
102	
103	  // ---------- Conta ----------
104	  app.post('/api/auth/register', rateLimit(20), async (req, res) => {
105	    const name = clean(req.body.name, 80);
106	    const email = clean(req.body.email, 120).toLowerCase();
107	    const password = String(req.body.password || '');
108	    const role = req.body.role === 'professor' ? 'professor' : 'aluno';
109	    if (name.length < 3) throw new HttpError(400, 'Digite seu nome completo.');
110	    if (!/^[^@\s]+@[^@\s]+$/.test(email)) throw new HttpError(400, 'E-mail inválido.');
111	    const domain = email.split('@')[1];
112	    if (!config.emailDomains.includes(domain)) {
113	      throw new HttpError(400, `Use seu e-mail institucional (${config.emailDomains.map((d) => '@' + d).join(' ou ')}).`);
114	    }
115	    if (password.length < 6) throw new HttpError(400, 'A senha precisa ter pelo menos 6 caracteres.');
116	    let courseId = null;
117	    let semester = null;
118	    if (role === 'professor') {
119	      if (clean(req.body.professorCode, 60).toUpperCase() !== config.professorCode.toUpperCase()) {
120	        throw new HttpError(400, 'Código de professor incorreto. Peça para a coordenação.');
121	      }
122	    } else {
123	      courseId = int(req.body.course_id);
124	      if (!courseId || !(await one('SELECT id FROM courses WHERE id = $1', [courseId]))) throw new HttpError(400, 'Escolha seu curso.');
125	      semester = Math.min(Math.max(int(req.body.semester) || 1, 1), 12);
126	    }
127	    if (await one('SELECT id FROM users WHERE email = $1', [email])) throw new HttpError(409, 'Já existe uma conta com esse e-mail.');
128	    const u = await one(
129	      `INSERT INTO users (email, password_hash, name, role, course_id, semester)
130	       VALUES ($1, $2, $3, $4, $5, $6) RETURNING id`,
131	      [email, hashPassword(password), name, role, courseId, semester],
132	    );
133	    await createSession(res, req, u.id);
134	    res.json({ ok: true });
135	  });
136	
137	  app.post('/api/auth/login', rateLimit(30), async (req, res) => {
138	    const email = clean(req.body.email, 120).toLowerCase();
139	    const u = await one('SELECT id, password_hash FROM users WHERE email = $1', [email]);
140	    if (!u || !checkPassword(req.body.password || '', u.password_hash)) throw new HttpError(401, 'E-mail ou senha incorretos.');
141	    await createSession(res, req, u.id);
142	    res.json({ ok: true });
143	  });
144	
145	  // Acesso rápido da banca: cria uma conta de visitante (sem e-mail e sem senha).
146	  app.post('/api/auth/banca', rateLimit(30), async (req, res) => {
147	    if (!config.bancaEnabled) throw new HttpError(403, 'O acesso da banca está desligado.');
148	    if (config.bancaCode && clean(req.body.code, 60).toLowerCase() !== config.bancaCode.toLowerCase()) {
149	      throw new HttpError(400, 'Código da banca incorreto.');
150	    }
151	    const name = clean(req.body.name, 60);
152	    if (name.length < 2) throw new HttpError(400, 'Digite seu nome.');
153	    const role = req.body.role === 'professor' ? 'professor' : 'aluno';
154	    let courseId = null;
155	    if (role === 'aluno') {
156	      courseId = int(req.body.course_id);
157	      if (!courseId || !(await one('SELECT id FROM courses WHERE id = $1', [courseId]))) throw new HttpError(400, 'Escolha um curso.');
158	    }
159	    const u = await one(
160	      `INSERT INTO users (name, role, course_id, semester, is_guest, bio)
161	       VALUES ($1, $2, $3, $4, TRUE, $5) RETURNING id`,
162	      [name, role, courseId, role === 'aluno' ? 8 : null, 'Membro da banca avaliadora 🎓'],
163	    );
164	    await createSession(res, req, u.id, 7);
165	    res.json({ ok: true });
166	  });
167	
168	  app.post('/api/auth/logout', async (req, res) => {
169	    await destroySession(req, res);
170	    res.json({ ok: true });
171	  });
172	
173	  app.get('/api/me', (req, res) => {
174	    res.json({ user: req.user ? meJson(req.user) : null });
175	  });
176	
177	  app.put('/api/me', requireUser, async (req, res) => {
178	    const u = req.user;
179	    const name = clean(req.body.name ?? u.name, 80);
180	    if (name.length < 2) throw new HttpError(400, 'Nome muito curto.');
181	    const bio = clean(req.body.bio ?? u.bio, 300);
182	    let courseId = u.course_id;
183	    let semester = u.semester;
184	    if (u.role === 'aluno') {
185	      const c = int(req.body.course_id);
186	      if (c && (await one('SELECT id FROM courses WHERE id = $1', [c]))) courseId = c;
187	      const s = int(req.body.semester);
188	      if (s) semester = Math.min(Math.max(s, 1), 12);
189	    }
190	    let avatarId = u.avatar_id;
191	    if (req.body.avatar) {
192	      avatarId = await saveImageFromDataUrl(req.body.avatar, u.id);
193	    }
194	    await q('UPDATE users SET name = $1, bio = $2, course_id = $3, semester = $4, avatar_id = $5 WHERE id = $6', [
195	      name, bio, courseId, semester, avatarId, u.id,
196	    ]);
197	    if (avatarId !== u.avatar_id && u.avatar_id) await q('DELETE FROM images WHERE id = $1', [u.avatar_id]);
198	    const trophies = await checkTrophies(u.id);
199	    res.json({ ok: true, trophies });
200	  });
201	
202	  // ---------- Feed e publicações ----------
203	  app.get('/api/feed', requireUser, async (req, res) => {
204	    const before = int(req.query.before);
205	    const userId = int(req.query.user);
206	    const courseId = req.query.scope === 'course' ? req.user.course_id : null;
207	    const kind = req.query.kind === 'foto' ? 'foto' : null;
208	    const limit = Math.min(int(req.query.limit) || 12, 60);
209	    const rows = await q(
210	      `${FEED_SELECT}
211	       WHERE ($2::int IS NULL OR (p.created_at, p.id) < (SELECT created_at, id FROM posts WHERE id = $2))
212	         AND ($3::int IS NULL OR u.course_id = $3)
213	         AND ($4::int IS NULL OR p.user_id = $4)
214	         AND ($5::text IS NULL OR p.kind = $5)
215	       ORDER BY p.created_at DESC, p.id DESC LIMIT ${limit}`,
216	      [req.user.id, before, courseId, userId, kind],
217	    );
218	    res.json({ posts: rows.map(decoratePost), more: rows.length === limit });
219	  });
220	
221	  app.post('/api/posts', requireUser, async (req, res) => {
222	    res.json(await createPost(req.user, req.body));
223	  });
224	
225	  app.get('/api/posts/:id', requireUser, async (req, res) => {
226	    const post = await one(`${FEED_SELECT} WHERE p.id = $2`, [req.user.id, int(req.params.id)]);
227	    if (!post) throw new HttpError(404, 'Publicação não encontrada.');
228	    const comments = await q(
229	      `SELECT cm.id, cm.body, cm.created_at, u.id AS user_id, u.name AS user_name, u.avatar_id AS user_avatar,
230	              u.role AS user_role, u.is_guest AS user_guest
231	         FROM comments cm JOIN users u ON u.id = cm.user_id
232	        WHERE cm.post_id = $1 ORDER BY cm.id ASC`,
233	      [post.id],
234	    );
235	    res.json({ post: decoratePost(post), comments });
236	  });
237	
238	  app.delete('/api/posts/:id', requireUser, async (req, res) => {
239	    await deletePost(req.user, int(req.params.id));
240	    res.json({ ok: true });
241	  });
242	
243	  app.post('/api/posts/:id/like', requireUser, async (req, res) => {
244	    res.json(await toggleLike(req.user, int(req.params.id)));
245	  });
246	
247	  app.post('/api/posts/:id/comments', requireUser, async (req, res) => {
248	    res.json(await addComment(req.user, int(req.params.id), req.body.body));
249	  });
250	
251	  app.delete('/api/comments/:id', requireUser, async (req, res) => {
252	    await deleteComment(req.user, int(req.params.id));
253	    res.json({ ok: true });
254	  });
255	
256	  // ---------- Pessoas ----------
257	  app.get('/api/users', requireUser, async (req, res) => {
258	    const term = clean(req.query.q, 60);
259	    const role = req.query.role === 'aluno' ? 'aluno' : null;
260	    const rows = await q(
261	      `SELECT u.id, u.name, u.role, u.avatar_id, u.is_guest, u.semester, c.short AS course
262	         FROM users u LEFT JOIN courses c ON c.id = u.course_id
