219	  const sameCourse = all.filter((r) => r.course_id === user.course_id);
220	  const course = sameCourse.findIndex((r) => r.id === user.id) + 1 || null;
221	  return { general, course, totalGeneral: all.length, totalCourse: sameCourse.length };
